SELECT m.id, m.symbol, m.entry_signal_id, m.status, m.quantity, m.average_entry_price_usdt, m.stop_loss_usdt, m.take_profit_usdt, m.highest_price_usdt, m.profit_lock_active, m.profit_lock_price_usdt, m.profit_lock_progress_percent, m.profit_lock_activated_at, m.profit_lock_state, m.profit_lock_rebase_started_at, m.entry_stage, m.allocated_position_percent, m.entry_quality_score, m.near_tp_state, m.near_tp_best_price, m.near_tp_harvest_used, m.near_tp_harvested_quantity, m.entry_confidence, m.entry_total_score, m.entry_decision, m.opened_at, m.updated_at FROM crypto_ai.wallet_managed_position m JOIN crypto_ai.paper_position p ON p.symbol = m.symbol AND m.opened_at BETWEEN p.opened_at - INTERVAL 1 MINUTE AND p.opened_at + INTERVAL 1 MINUTE WHERE p.id IN (182,172,162,158,143,137) ORDER BY m.opened_at;